async def add_hour(
    executor: edgedb.AsyncIOExecutor,
    *,
    sub_group: int,
    occupation: str,
    number: int,
) -> AddHourResult:
    return await executor.query_single(
        """\
        insert Hour {
          sub_group := <int16>$sub_group,
          occupation := <str>$occupation,
          number := <int16>$number,
        };\
        """,
        sub_group=sub_group,
        occupation=occupation,
        number=number,
    )


async def add_hour_with_cabinet(
    executor: edgedb.AsyncIOExecutor,
    *,
    cabinet_number: str,
    cabinet_details: str,
    sub_group: int,
    occupation: str,
    number: int,
) -> AddHourResult:
    return await executor.query_single(
        """\
        with cabinet := (
          insert Cabinet {
            number := <str>$cabinet_number,
            details := <str>$cabinet_details
          } unless conflict on .number else Cabinet
        )

        insert Hour {
          sub_group := <int16>$sub_group,
          occupation := <str>$occupation,
          cabinet := cabinet,
          number := <int16>$number,
        };\
        """,
        cabinet_number=cabinet_number,
        cabinet_details=cabinet_details,
        sub_group=sub_group,
        occupation=occupation,
        number=number,
    )


async def add_study_day(
    executor: edgedb.AsyncIOExecutor,
    *,
    group_full_name: str,
    group_name: str,
    hour_ids: list[uuid.UUID],
    date: datetime.datetime,
) -> AddStudyDayResult:
    return await executor.query_single(
        """\
        with
          `group` := (
            insert `Group` {
              full_name := <str>$group_full_name,
              name := <str>$group_name
            } unless conflict on (.full_name, .name) else `Group`
          ),
          hours := (
            select Hour filter .id in array_unpack(<array<uuid>>$hour_ids)
          )

        insert StudyDay {
          `group` := `group`,
          hours := hours,
          date := <datetime>$date
        } unless conflict on (.`group`, .date) else StudyDay;\
        """,
        group_full_name=group_full_name,
        group_name=group_name,
        hour_ids=hour_ids,
        date=date,
    )
